  "settingsSaveFailed": "Не удалось сохранить",
  "settingsSchemeAutoDesc": "Консервативный: учитывается только стандартный API Window Controls Overlay (реальная высота наложения заголовка); обычные веб-среды не изменяются",
  "settingsSchemeAutoTitle": "Автоопределение",
  "settingsSchemeCustomDesc": "Полный контроль: вставьте пользовательский CSS (может переопределять встроенные стили) и задайте расстояние смещения строки заголовка",
  "settingsSchemeCustomTitle": "Настроить",
