  "settingsSchemeWebDesc": "Явно указать официальный веб-интерфейс: без адаптации вообще (даже стандартной геометрии WCO)",
  "settingsSchemeWebTitle": "Официальный сайт DSH",
  "settingsShellArgsDesc": "Явные аргументы командной оболочки, разделённые пробелами; если не пусто, полностью заменяют значения по умолчанию (тот же принцип, что и у shellArgs в yaml)",
  "settingsShellArgsPlaceholder": "напр. -l (пусто = по умолчанию)",
  "settingsShellArgsTitle": "Аргументы командной оболочки",
  "settingsShellDesc": "Оболочка, запускаемая для терминалов UI и моделей (абсолютный путь или имя исполняемого файла). Пустое значение сохраняет устаревший порядок: shell из конфига yaml → $SHELL / логин-шелл / Windows powershell.exe. Применяется к терминалам, открытым после этого.",
